export const lang = () => localStorage.getItem('eruldin.lang') || 'tr';
export const t = k => STR[lang()]?.[k] ?? STR.tr[k] ?? k;
export const tn = (obj, fallback = '') => obj ? (obj[lang()] ?? obj.tr ?? fallback) : fallback;
export const setLang = l => { localStorage.setItem('eruldin.lang', l); document.documentElement.lang = l; };
